  "Gecenin en çok paylaşılan anı senin yumruğun.": "O momento mais compartilhado da noite é o seu golpe.",
  "Yorumcular nakavtı “yılın nakavtı” adayı ilan etti.": "Os comentaristas chamaram de candidato a “nocaute do ano”.",
  "Yer benim evim. Oraya gelen herkes tap atar.": "O chão é minha casa. Todo mundo que desce ali bate.",
  "Kolunu kırmak istemedim, tap attığı iyi oldu.": "Eu não queria quebrar o braço dele, ainda bem que bateu.",
  "Anakonda gibi sardım. Nefes alamadı.": "Enrolei ele como uma anaconda. Ele não conseguia respirar.",
  "Yorumcular seni sıkletin en tehlikeli yer dövüşçüleri arasında saymaya başladı.": "Os comentaristas começam a te chamar de um dos grapplers mais perigosos da categoria.",
  "Güreşçiler artık seninle yere inmekten korkacak.": "Agora os wrestlers vão ter medo de ir ao chão com você.",
  "Isınamadım bile! Organizasyon bana daha zor bir rakip bulsun.": "Nem aqueci! A organização devia me arrumar um adversário mais duro.",
  "Maaşımın dakikası kaç para etti, hesaplayın!": "Façam a conta de quanto ganhei por minuto!",
  "Planım üç rauntluktu, bir raunt yetti.": "Meu plano era para três rounds, bastou um.",
  "“Isınamadım bile” cümlesi meme oldu!": "“Nem aqueci” virou meme!",
  "Matchmaker’lar isteğini ciddiye aldı.": "Os matchmakers levaram seu pedido a sério.",
  "{maxRaunt} raunt boyunca ona ders verdim. Bir dahakine bitireceğim.": "Dei aula por {maxRaunt} rounds. Da próxima vez eu finalizo.",
  "Satranç oynadım, o dama oynadı.": "Eu jogava xadrez, ele jogava dama.",
  "Her raundu aldım, her pozisyonu kazandım.": "Venci todos os rounds, venci todas as posições.",
  "Bazıları “sıkıcı” dedi, ama kimse üstünlüğünü tartışmıyor.": "Alguns chamaram de “chato”, mas ninguém discute seu domínio.",
  "Teknik direktörler performansını analiz etti: “ders niteliğinde”.": "Treinadores analisaram sua atuação: “uma aula”.",
  "Zor bir geceydi. Bir dahaki sefere işi hakemlere bırakmayacağım.": "Foi uma noite dura. Da próxima vez não deixo na mão dos juízes.",
  "Hakemler bana verdi ama {opp} de kazanmayı hak ediyordu.": "Os juízes me deram a vitória, mas {opp} também merecia vencer.",
  "Dürüst bir itiraf. Taraftarlar sana saygı duydu.": "Uma confissão honesta. Os fãs te respeitaram por isso.",
  "Rakibin bile bu sözleri paylaştı.": "Até o seu adversário compartilhou essas palavras.",
  "Açık ara kazandım! Bunu tartışan maçı izlememiş.": "Venci claramente! Quem discorda não viu a luta.",
  "Ayrık karar mı? Hakemlerin gözlüğe ihtiyacı var, açık ara bendeydi.": "Decisão dividida? Os juízes precisam de óculos, foi claramente minha.",
  "Taraftarların arkanda durdu, tartışma seni daha çok konuşturdu.": "Seus fãs te apoiaram, a polêmica te deu ainda mais atenção.",
  "Yuhalandın. Kararı bu kadar net görmeyen çok kişi vardı.": "Você foi vaiado. Muita gente não viu a decisão tão clara.",
  "Herkes bitti sandı. Ben bitmem!": "Todo mundo achou que eu estava acabado. Eu nunca estou acabado!",
  "Rauntları kaybediyordum, köşem bana inandı. Kalbim kazandı bu maçı.": "Eu perdia os rounds, meu córner acreditou em mim. Meu coração venceu esta luta.",
  "Geriden gelmek bir karakter meselesi.": "Virar a luta é questão de caráter.",
  "Geri dönüşün “gecenin hikâyesi” oldu.": "Sua virada virou “a história da noite”.",
  "Kimse ayağa kalkmadan oturmadı. Efsanevi bir dönüş.": "Ninguém sentou. Uma virada lendária.",
  "Beni yere indirdi, ama asıl önemli olan kalkmak.": "Me derrubaram, mas o que importa é levantar.",
  "Tavanı gördüm, sonra onun çenesini gördüm!": "Eu vi o teto, depois vi o queixo dele!",
  "Yere düştüm, kalktım, kazandım. Hayat da böyle.": "Caí, levantei e venci. Assim é a vida.",
  "Çenen ve yüreğin tartışılmaz oldu.": "Seu queixo e seu coração já não se discutem.",
  "Bu dayanıklılık hikâyesi motivasyon videolarına girdi.": "Essa história de superação foi parar nos vídeos motivacionais.",
  "Kimse benim kazanacağımı düşünmüyordu. Bahis oranları şimdi ne diyor?": "Ninguém achava que eu ia vencer. O que dizem as casas de apostas agora?",
  "Favori mi? Artık favori benim.": "Favorito? Agora o favorito sou eu.",
