  "{hedef}, bu kemere giden yolda sen varsın. Çekil ya da savaş!": "{hedef}, você está no meu caminho para o cinturão. Sai da frente ou luta!",
  "Salon inledi. {0} kamerasına bakıp başını salladı. Organizasyon bu maçı düşünüyor.": "A arena rugiu. {0} olhou para a câmera e assentiu. A organização está considerando esta luta.",
  "{0} sosyal medyadan cevap verdi: “Tamam.” Maç konuşuluyor!": "{0} respondeu nas redes: “Fechado.” A luta está sendo comentada!",
  "Salon sessiz kaldı. {0} cevap bile vermedi.": "A arena ficou em silêncio. {0} nem respondeu.",
  "{0} güldü: “Önce sıranı bekle.”": "{0} riu: “Primeiro espera sua vez.”",
  "Şampiyon {sampiyon}! Kemerini parlat, geliyorum!": "Campeão {sampiyon}! Pode lustrar o cinturão, estou chegando!",
  "{sampiyon}, o kemer benim belimde daha güzel duracak.": "{sampiyon}, esse cinturão vai ficar melhor na minha cintura.",
  "Kafeste {sampiyon}’ı görmek istiyorum. Şimdi!": "Quero ver {sampiyon} no octógono. Agora!",
  "Şampiyon kafese girdi, burun buruna geldiniz! Görüntüler her yerde. Ünvan maçı konuşuluyor.": "O campeão entrou no octógono e vocês ficaram cara a cara! O vídeo está em todo lugar. Fala-se em disputa de título.",
  "Şampiyon güldü: “Önce sırana gir.” Sosyal medyada alay konusu oldun.": "O campeão riu: “Primeiro entra na fila.” As redes zoaram você.",
