  "Dünya basını manşette: TARİH YAZILDI!": "Manchete da imprensa mundial: HISTÓRIA!",
  "Organizasyon başkanı iki kemeri birlikte taktı. Salon yıkıldı.": "O presidente da organização colocou os dois cinturões em você. A arena explodiu.",
  "Bu tahtı kimseye bırakmam. Sıradaki gelsin!": "Não entrego este trono a ninguém. Quem é o próximo!",
  "Kemer benim belimde, sıklet benim evim.": "O cinturão está na minha cintura, esta categoria é minha casa.",
  "Kral hâlâ burada!": "O rei continua aqui!",
  "Şampiyon edası. Sıklet sana meydan okumak için sıraya girdi.": "Pose de campeão. A categoria faz fila para te desafiar.",
  "Hükümdarlığın tartışılmaz.": "Seu reinado é indiscutível.",
  "{orgKisa}, o bonus çeki benim adıma yazılsın!": "{orgKisa}, faz esse cheque do bônus no meu nome!",
  "Bonusumu istiyorum, ev taksitlerim var!": "Quero meu bônus, tenho parcelas da casa pra pagar!",
  "Organizasyon başkanı gülerek “Hak etti” dedi ve ek ${0} verdi!": "O presidente da organização riu, disse “Ele mereceu” e deu ${0} extra!",
  "Başkan omuz silkti: “Bonusları ben dağıtırım.” Yine de taraftarlar sevdi.": "O presidente deu de ombros: “Quem distribui bônus sou eu.” Os fãs adoraram mesmo assim.",
  "UCC, beni izliyorsanız: hazırım!": "UCC, se estiver assistindo: estou pronto!",
  "Dean Wyatt, telefon numaram değişmedi!": "Dean Wyatt, meu número continua o mesmo!",
  "{0} bu sözlerden hiç hoşlanmadı. Sonraki dövüş ücretin %10 kesildi.": "A {0} não gostou nada dessas palavras. 10% foram descontados da sua próxima bolsa.",
  "UCC’nin resmi hesabı videonu paylaştı! Radardasın.": "A conta oficial do UCC compartilhou seu vídeo! Você está no radar.",
