  "{ph} ile aynı kafese girmek için sabırsızlanıyorum. Sabırsızlığım onun korkusundan büyük. 😈": "Não vejo a hora de entrar no octógono com {ph}. Minha impaciência é maior que o medo dele. 😈",
  "Kamp raporu: {ph} dövüşünü 100 kez izledim. Açığını buldum. Sürpriz olmayacak.": "Atualização do camp: vi {ph} lutar 100 vezes. Achei o buraco. Sem surpresas.",
  "Bahis tavsiyesi: {ph} aleyhine her şeyinizi yatırın. 💰": "Dica de aposta: joguem tudo contra {ph}. 💰",
  "{ph}’ın hocası bile bu maçı kabul ettiği için ona kızıyormuş. 😂": "Até o treinador de {ph} está bravo com ele por aceitar esta luta. 😂",
  "Tartıda göz göze geleceğiz {ph}. Gözlerini kaçırma.": "Vamos nos encarar na pesagem, {ph}. Não desvia o olhar.",
  "{ph} sıkletin en abartılı ismi. {hafta} hafta sonra balon patlıyor. 🎈": "{ph} é o nome mais superestimado da categoria. Em {hafta} semanas a bolha estoura. 🎈",
  "{ph} mi? {org}’da bana verilen en kolay maç bu. {hafta} hafta sonra görürüz.": "{ph}? A luta mais fácil que a {org} já me deu. Te vejo em {hafta} semanas.",
  "{ph} kafeste görüşürüz. Hastane masrafını ben öderim, merak etme.": "Te vejo no octógono, {ph}. A conta do hospital é por minha conta, relaxa.",
  "Çenen cam gibi {p}. İlk sağ elimde dağılacak.": "Seu queixo é de vidro, {p}. Vai quebrar na minha primeira direita.",
  "{ph} sosyal medyada çok cesur. Bakalım kafes kapısı kapanınca da öyle mi?": "{ph} é muito corajoso nas redes. Vamos ver se isso dura quando a porta do octógono fechar.",
  "Herkes {p} diyor… Ben kimseyi görmüyorum. 🥱": "Todo mundo fala de {p}… eu não vejo ninguém. 🥱",
  "{ph} taraftarlarına söyleyin, mendillerini hazırlasınlar.": "Avisem os fãs de {ph} para prepararem os lencinhos.",
  "{ph} kariyerini takip ediyorum, ciddi bir yetenek. Ama bu gece benim gecem olacak.": "Acompanho a carreira de {ph}, talento sério. Mas esta noite será minha.",
  "Bu maç ikimiz için de büyük fırsat. {ph}, sağlıklı bir kamp dilerim.": "Esta luta é uma grande oportunidade para nós dois. {ph}, tenha um bom camp.",
  "{ph} ile dövüşmek onur. Hazırlığım tam, en iyi hâlimle geleceğim.": "Uma honra lutar com {ph}. Minha preparação está completa, vou chegar no meu melhor.",
  "Saygı duyduğum bir rakip: {ph}. Ama kazanan ben olacağım.": "Um adversário que respeito: {ph}. Mas quem vai vencer sou eu.",
  "Kamp bitti. {ph}, iyi bir savaş olsun. 🤝": "Camp encerrado. {ph}, vamos fazer uma boa guerra. 🤝",
  "{ph} söylemiştim. Sıradaki! 👋": "Eu avisei, {ph}. Próximo! 👋",
  "Bu gece bir şey kanıtladım. {ph}, iyi dövüştün ama yeterli değildi.": "Provei algo esta noite. {ph}, você lutou bem, mas não bastou.",
  "Kemer yolu devam ediyor. {ph} sadece bir basamaktı.": "O caminho até o cinturão continua. {ph} foi só um degrau.",
  "{ph} bu gece daha iyiydi. Tebrikler şampiyon adayı. Geri döneceğim.": "{ph} foi melhor esta noite. Parabéns, futuro campeão. Eu volto.",
  "Ders aldım. {ph} gerçek bir savaşçı. 🤝": "Lição aprendida. {ph} é um verdadeiro guerreiro. 🤝",
  "Hakemler bu gece beni soydu. {ph} bunu biliyor.": "Os juízes me roubaram esta noite. {ph} sabe disso.",
  "Şanslı yumruktu {ph}. Rövanşta gerçeği göreceksin.": "Soco de sorte, {ph}. Você vai ver a verdade na revanche.",
  "Tek kelime: RÖVANŞ. {ph} kaçmasın.": "Uma palavra: REVANCHE. É bom {ph} não fugir.",
  "{p} maçını 5. kez izliyorum, hâlâ doyamadım 🔥": "Vendo a luta de {p} pela 5ª vez e ainda não enjoei 🔥",
  "Babam 40 yıldır maç izler, “böylesini görmedim” dedi.": "Meu pai assiste luta há 40 anos e disse “nunca vi nada igual”.",
  "Bu adamın posteri odamda artık 🥊": "O pôster desse lutador já está na minha parede 🥊",
  "{p} sıkletin geleceği değil, bugünü!": "{p} não é o futuro da categoria, é o presente!",
  "O kombinasyon ne öyle?! Geri sar, geri sar!": "Que combinação foi essa?! Volta, volta!",
  "Salon arkadaşlarımla izledik, ortalık yıkıldı 😂": "Assisti com o pessoal da academia, o lugar enlouqueceu 😂",
  "{p} geleceğin şampiyonu!! 🔥🔥": "{p} é futuro campeão!! 🔥🔥",
  "Bu adamı izlemek bir zevk. Kemer an meselesi.": "Um prazer assistir. O cinturão é questão de tempo.",
  "{memleket} gurur duyuyor! 🇹🇷💪": "{memleket} está orgulhosa! 💪",
  "Az önce {p} maçını izledim, tüylerim diken diken.": "Acabei de ver a luta de {p}, estou arrepiado.",
  "Bir sonraki maçına bilet alıyorum, kimse beni durduramaz.": "Comprando ingresso para a próxima luta, ninguém me segura.",
  "Oyun planı felaketti. Hoca değişmeli.": "O plano de luta foi um desastre. O treinador tem que sair.",
  "Kötü gün herkesin başına gelir. {p} döner.": "Todo mundo tem um dia ruim. {p} vai voltar.",
  "Bu kadar hype’a bu performans mı? 🤡": "Todo aquele hype para essa atuação? 🤡",
  "{p} kampta tatil mi yaptı acaba?": "{p} tirou férias em vez de fazer camp?",
  "Kafam hâlâ inanmıyor ya… ❤️‍🩹": "Ainda não acredito… ❤️‍🩹",
  "{p} abartılıyormuş, belli oldu.": "Pelo jeito {p} era superestimado mesmo.",
  "Üzülme {p}, büyük şampiyonlar da kaybeder. Kalk ayağa! ❤️": "Não fica triste, {p}, grandes campeões também perdem. Levanta! ❤️",
  "Kamp değişmeli. Bu oyun planı neydi?": "O camp tem que mudar. Que plano de luta foi aquele?",
  "Hâlâ arkandayız {p}. 💪": "Seguimos com você, {p}. 💪",
  "HAHAHA efsane 😂🔥": "KKKKKK lendário 😂🔥",
  "Bu adamın ağzı da yumrukları kadar sert!": "A boca desse lutador é tão dura quanto os golpes!",
  "Gerilim tırmanıyor, bu maçı kaçırmam!": "A tensão está crescendo, não perco essa luta!",
  "Önce bir kemer al, sonra konuş.": "Primeiro ganha um cinturão, depois fala.",
  "Çok konuşan az dövüşür.": "Quem mais fala é quem menos luta.",
  "Bu biraz fazlaydı…": "Isso foi um pouco demais…",
  "Saygılı sporcu = gerçek sporcu 👏": "Atleta respeitoso = atleta de verdade 👏",
