  "Karakterini Nasıl Kurarsın?": "Como você cria seu personagem?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Nacionalidade: as opções de treino definem seus atributos iniciais e o apoio da torcida sua popularidade inicial. Sua primeira academia e treinador também dependem do país.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Idade (18-30): começando jovem você é cru, mas evolui rápido (×1,3). Começando mais velho você é mais forte, mas depois dos 32 a velocidade e o queixo começam a cair. A aposentadoria é inevitável aos 41.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Categoria: os pesos leves são rápidos e resistentes; os pesados batem forte, mas cansam rápido.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Base: a escolha mais importante. Define seus pontos fortes e fracos e, com isso, como você luta.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 História: escreva você mesmo ou deixe o jogo escrever.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Dados: no último passo seus atributos são sorteados. Não gostou? Pode rolar de novo duas vezes.",
  "Gelişim Puanı": "Pontos de habilidade",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Você começa a carreira com 3 pontos. Cada camp dá 1-3 pontos (conforme intensidade, idade, local, treinador e qualidade da equipe). A área de foco do camp também melhora +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "As lutas também dão pontos: vitória 2, finalização +1, bônus +1, cinturão +1. Derrota e empate 1 ponto.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Um ciclo de luta (camp + recuperação) leva cerca de 90-100 dias. Você luta 3-4 vezes por ano; cada decisão conta.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Gaste os pontos no atributo que quiser. Até 50, +1 custa 1 ponto; até 70, 2; até 85, 3; depois, 4 pontos.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Você pode gastá-los antes da pesagem no fim do camp, depois de uma luta ou na aba EVOLUÇÃO da tela de carreira.",
  "Nasıl Oynanır?": "Como jogar",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Escolha o adversário. Na fase regional você escolhe; nas grandes organizações ele é definido.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Camp: área de foco, plano de luta, intensidade, corte de peso e coletiva. Um plano que ataque a fraqueza do adversário dá grande vantagem no octógono.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Luta: escolha uma tática a cada round. Nos momentos críticos (adversário balançado, finalização encaixada) você decide rápido.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Depois: bônus, entrevista, ranking, ofertas de contrato e eventos entre as lutas.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 O caminho: Amador → Regional (CFC, Hexagon) → Grande (PFC, ZEN, VIP) → DWCS ou última hora → cinturão do UCC.",
  "BOŞ YUVA": "ESPAÇO VAZIO",
  "Yeni bir kariyere başla": "Começar uma nova carreira",
  " · SON OYNANAN": " · ÚLTIMA PARTIDA",
