  "Yeni kariyer": "Nova carreira",
  "KAFESTEN KEMERE": "DO OCTÓGONO AO CINTURÃO",
  "Sıfırdan UCC şampiyonluğuna. Her karar senin.": "Do zero a campeão do UCC. Cada decisão é sua.",
  "Çevrimdışı oynamaya hazır · sürüm {0}": "Pronto para jogar offline · versão {0}",
  "Yeni sürüm indiriliyor… uygulamayı kapatma": "Baixando nova versão… não feche o app",
  "Çevrimdışı için indiriliyor{0}": "Baixando para jogar offline{0}",
  "KARİYER YUVALARI": "ESPAÇOS DE CARREIRA",
  "Saat gece 02:14. Şehrin kenarında, tabelasının yarısı yanmayan bir spor salonu var.": "São 2h14 da madrugada. Na periferia da cidade há uma academia com metade do letreiro apagado.",
  "İçeride tek bir ampul yanıyor. Duvarda solmuş bir poster var: sekizgen bir kafes ve havaya kaldırılmış altın bir kemer.": "Lá dentro, uma única lâmpada acesa. Na parede, um pôster desbotado: um octógono e um cinturão dourado erguido no alto.",
