  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "No topo estão seu dinheiro, sua saúde e sua popularidade. Quando estiver pronto, escolha o adversário em “MARCAR LUTA”. Nas semanas entre as lutas, a loja, as redes e a vida noturna te esperam; mas lembre, tudo tem um preço.",
  "Gelişim puanları": "Pontos de habilidade",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Você ganha pontos nos camps e nas lutas e distribui nos atributos aqui. Acima de 50 cada ponto custa mais; cobrir seu ponto fraco costuma ser mais inteligente.",
  "Rakibini seç": "Escolha seu adversário",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Cada adversário mostra força e ponto fraco. Um adversário fácil é seguro, mas rende pouco; vença um arriscado e você dá um grande salto no ranking.",
  "Kamp başlıyor": "O camp está começando",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Primeiro escolha a duração do camp. Um camp longo te desenvolve mais, mas é caro e desgasta. Nas semanas livres antes do camp você pode treinar técnica e fazer sparring.",
  "Oyun planı": "Plano de luta",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Um plano que ataca a fraqueza do adversário dobra o efeito na luta. Veja o relatório de scouting e escolha seu plano.",
  "Burun buruna": "Cara a cara",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Depois da pesagem você vai encarar o adversário. Sua atitude pode abalar o moral dele ou sair caro para você.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Escolha uma tática no início de cada round e a luta flui sozinha. Quando o adversário balançar ou surgir uma finalização, você precisa decidir rápido. Fique de olho no cardio: cansado, tudo fica mais difícil.",
  "Dövüş bitti": "A luta acabou",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "O microfone é seu: o que você diz na entrevista afeta sua popularidade. Gaste os pontos ganhos na aba EVOLUÇÃO. Uma grande vitória? Compartilhe para todo mundo ver!",
  "Google Play’de ücretsiz": "Grátis no Google Play",
