  "Kalan adımları biz seçelim: branş, sıklet, görünüm ve hikâye. Hemen salona gir, her şeyi sonradan oynarken öğrenirsin.": "A gente escolhe o resto: modalidade, categoria, visual e história. Vá direto para a academia e aprenda jogando.",
  "Hemen başla": "Começar agora",
  "ya da DEVAM ile karakterini adım adım kendin kur": "ou toque em CONTINUAR para montar seu lutador passo a passo",
  "🏁 Rekabet bitti! {0} sonunda kabul etti: \"Sen daha iyiydin, {1}.\" Aranızdaki seri: {2}. Popülerlik +5.": "🏁 A rivalidade acabou! {0} finalmente admitiu: \"Você foi melhor, {1}.\" Série: {2}. Popularidade +5.",
  "Bugün kafeste daha iyi olan kazandı. Saygılar {0}. Bu rekabet beni daha iyi bir dövüşçü yaptı.": "Hoje o melhor venceu. Respeito, {0}. Essa rivalidade me fez um lutador melhor.",
  "🏁 {0} emekliliğini açıkladı: \"Kariyerimdeki en zor rakip sendin, {1}.\" Seriyi sen kazandın: {2}.": "🏁 {0} anunciou a aposentadoria: \"Você foi o adversário mais duro da minha carreira, {1}.\" Você venceu a série: {2}.",
  "🏁 {0} emekliliğini açıkladı. Aranızdaki seri: {1}. Onu hiç tam geçemedin; bu hikâye böyle bitti.": "🏁 {0} anunciou a aposentadoria. Série: {1}. Você nunca chegou a superá-lo; é assim que essa história termina.",
  "⚔️ Ezeli rakibin {0} karşısında kazandın! Aranızdaki seri: {1}.": "⚔️ Você venceu seu arquirrival {0}! Série: {1}.",
  "Bu gece senin gecendi. Ama bu iş bitmedi, {0}.": "Hoje a noite foi sua. Mas isso não acabou, {0}.",
  "Rövanş istiyorum. Organizasyon duysun!": "Quero a revanche. Que o evento ouça!",
  "Şans bir kez güler. Üçüncü maçta görüşürüz.": "A sorte só sorri uma vez. Nos vemos na próxima.",
  "⚔️ Ezeli rakibinle berabere. Aranızdaki seri: {0}. Kimse tatmin olmadı.": "⚔️ Empate com seu arquirrival. Série: {0}. Ninguém ficou satisfeito.",
  "⚔️ {0} yine kazandı. Aranızdaki seri: {1}. Bu iş bitmedi.": "⚔️ {0} venceu de novo. Série: {1}. Isso não acabou.",
  "Söylemiştim. Kafeste ne zaman karşılaşsak aynı son. 😏": "Eu avisei. Toda vez que nos encontramos no octógono, o mesmo final. 😏",
  "{0}, bir daha karşıma çıkmadan önce iki kere düşün.": "{0}, pense duas vezes antes de me enfrentar de novo.",
  "Kral benim. Anlaşıldı mı?": "O rei sou eu. Entendeu?",
  "🗡️ {0} maçtan sonra mikrofonu aldı: \"Bu daha başlangıç. Kafeste her karşılaştığımızda aynı sonuç olacak.\" Bu isim peşini kolay bırakmayacak: artık bir ezeli rakibin var.": "🗡️ {0} pegou o microfone depois da luta: \"Isso é só o começo. Toda vez que nos encontrarmos no octógono, vai terminar igual.\" Esse nome não vai te largar tão cedo: agora você tem um arquirrival.",
  "{0} iyi dövüşçü ama bana göre değil. Ne zaman isterse tekrar.": "{0} é um bom lutador, mas não está no meu nível. Quando quiser, de novo.",
  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} falou para as câmeras: \"Todo mundo acha que {1} é invencível. Eu vou estourar essa bolha.\" Você tem um novo arquirrival.",
  "{0}, kaçamazsın. Sıra bende.": "{0}, você não pode fugir. Eu sou o próximo.",
  "{1} karşısında kazanmak mı? Onu ben de yenerdim. Asıl sınav benim, {0}.": "Vencer {1}? Eu também venceria. O verdadeiro teste sou eu, {0}.",
  "Herkes seni konuşuyor {0}. Ben hâlâ o geceyi hatırlıyorum. 😏": "Todo mundo fala de você, {0}. Eu ainda lembro daquela noite. 😏",
  "Güzel galibiyet {0}. Ama bir gün yine karşılaşacağız.": "Boa vitória, {0}. Mas um dia vamos nos encontrar de novo.",
  "{0} formda görünüyor. Ben de. Tarih verin.": "{0} parece em forma. Eu também. Marquem a data.",
  "{1} bile seni yendi. Ben sana söylemiştim, {0}.": "Até {1} te venceu. Eu te avisei, {0}.",
  "Kafeste yerin yok, {0}. Bunu en iyi ben biliyorum.": "Você não pertence ao octógono, {0}. Ninguém sabe disso melhor do que eu.",
  "🏆 UNVAN SAVUNMASI · EZELİ RAKİP": "🏆 DEFESA DE TÍTULO · ARQUIRRIVAL",
  "Sana meydan okudu. Kafeste cevap verme zamanı.": "Ele te desafiou. Hora de responder no octógono.",
