  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Quando o adversário prepara um golpe, um anel aparece encolhendo. Quando ficar DOURADO, aperte ESQUIVA e bata na hora: contragolpes causam o dobro.",
  "Vur ve kes": "Bata e interrompa",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "O JAB é rápido e barato; DIRETO e CHUTE são pesados. Solte um DIRETO ou CHUTE durante a preparação para interrompê-la. A barra amarela é seu fôlego: quando acaba, seus golpes enfraquecem.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Tente a QUEDA; se ele entrar com ⬇️, faça sprawl com ESQUIVA. No chão os botões mudam: por cima, bata e busque a finalização; por baixo, ESCAPE assim que vir 🔒.",
