  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Convite para o Grand Prix Ascensão! 8 amadores, um troféu: campeão e finalista abrem a porta profissional.",
  "🏆 Yükseliş Grand Prix'ine katıldın: 8 amatör, üç maç. Profesyonel organizasyonlar izliyor.": "🏆 Você entrou no Grand Prix Ascensão: 8 amadores, três lutas. As organizações profissionais estão de olho.",
