  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 Você venceu o Grand Prix Ascensão! As organizações fazem fila: a porta profissional está escancarada.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Você perdeu a final, mas todos assistiram. As organizações profissionais querem você no elenco!",
