  "“Kafes kapısında görüşürüz.” Bir sonraki rakip seçiminde {0} karşına çıkacak. Popülerlik +2.": "“Nos vemos na porta do octógono.” {0} aparecerá na sua próxima escolha de adversário. Popularidade +2.",
