  "{0} çocuk judo kursunda ilk kuşağını aldı. Törende hocasına değil, tribündeki sana dönüp eğildi.": "{0} ganhou a primeira faixa no judô infantil. Na cerimônia, curvou-se para você na arquibancada, não para o mestre.",
