  "🌍 Eski rakibin {0}, şampiyon olarak eldivenlerini astı.": "🌍 Seu antigo rival {0} se aposentou como campeão.",
  "🌍 Bir zamanlar yendiğin {0} emekli oldu.": "🌍 {0}, que você venceu, se aposentou.",
