  "Kopma noktasında": "No limite",
  "🤝 {0} ile aranız çok iyi: köşedeki her sözü tam zamanında geliyor (IQ +1).": "🤝 Você e {0} estão em sintonia: cada palavra do córner chega na hora certa (QI +1).",
  "🧊 {0} ile aranız soğuk: köşede konuşmalar kısa ve gergin (IQ -1).": "🧊 O clima com {0} está frio: no córner, conversas curtas e tensas (QI -1).",
  "{0}: “Seninle gurur duyuyorum. Şimdi git ve al şunu.”": "{0}: “Tenho orgulho de você. Agora vai lá e pega.”",
  "{0} yalnızca “Planı biliyorsun.” dedi. Sesi soğuktu.": "{0} só disse: “Você sabe o plano.” A voz estava fria.",
  "💢 Hocanla Kriz": "💢 Crise com o Treinador",
  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Depois do treino, {0} te chamou de lado: “Você não me escuta. Se for continuar assim, vamos seguir caminhos separados.”",
  "Özür dile, yeniden başlayalım": "Pedir desculpas e recomeçar",
  "Maaşına zam yap ({0})": "Dar um aumento ({0})",
  "Yollarınızı ayırın": "Seguir caminhos separados",
  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Você engoliu o orgulho. {0} assentiu: “Amanhã às seis.” O laço se recupera, motivação -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "O aumento ajudou, mas o que importou foi sentar e conversar. O laço ficou mais forte.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Você e {0} se separaram. Seu novo treinador é {1}. Vai ser preciso construir confiança do zero. Motivação -1.",
  "🫂 Bir Baba Gibi": "🫂 Como um Pai",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "À noite, sozinhos na academia, {0} tirou uma foto antiga: seu primeiro treino, luvas maiores que as mãos. “No dia em que você entrou por aquela porta, eu soube”, disse.",
  "Sarıl": "Abraçá-lo",
  "“Her şeyi sana borçluyum.”": "“Devo tudo a você.”",
  "{0} ile ilk antrenman fotoğrafı": "Foto do primeiro treino com {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Luvas maiores que as mãos. No verso, com a letra do treinador: “Um dia.”",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Vocês ficaram muito tempo sem falar. Não precisava. Motivação +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "“Não”, disse, “você deve tudo a si mesmo. Eu só abri a porta.” Motivação +2.",
  "📨 Rakip Kampın Teklifi": "📨 Proposta de um Camp Rival",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Uma grande academia ofereceu ao seu treinador {0} o cargo de técnico principal pelo dobro do salário. Ele não te contou; você soube por outro.",
  "Ona zam yap ve kalmasını iste ({0})": "Dar um aumento e pedir que fique ({0})",
  "Onu tebrik et, gitmesine izin ver": "Parabenizá-lo e deixá-lo ir",
  "Sessiz kal, kararı ona bırak": "Ficar calado e deixar que ele decida",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} recusou: “Meu lutador está aqui.” O laço ficou muito mais forte.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} saiu emocionado e, ao sair, te apresentou ao novo treinador {1}. Motivação +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} ficou. “Eu deveria ter decidido sem te perguntar, mas aqui é minha casa”, disse.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} aceitou a proposta. Seu novo treinador é {1}.",
  "🏥 Hocanın Sağlığı": "🏥 A Saúde do Treinador",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} está tossindo há semanas. Os médicos mandaram descansar, mas ele não quer largar o camp.",
  "Zorla tatile gönder, kampı asistan yönetsin": "Obrigá-lo a descansar; o assistente toca o camp",
  "Onun kararına saygı duy": "Respeitar a decisão dele",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Primeiro ficou bravo, depois agradeceu. Um mês depois voltou mais forte. O laço cresceu.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Ele tocou o camp, mas você se preocupou toda noite. Motivação -1.",
  "🕊️ Hocanın Vedası": "🕊️ A Despedida do Treinador",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} te chamou para o meio da academia: “Estou ficando velho, garoto. Te ensinei tudo o que sei.” Sugeriu o assistente para o lugar dele.",
  "Son bir antrenman yapın": "Fazer um último treino",
  "Veda yemeği düzenle": "Organizar um jantar de despedida",
  "{0} ile son fotoğraf": "Última foto com {0}",
  "Son antrenmanın sonunda minderde yan yana": "Lado a lado no tatame depois do último treino",
  "Veda yemeğinde, bütün salon bir arada": "No jantar de despedida, a academia toda reunida",
