  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Um produtor quer você como vilão no filme de ação “{0}”. Três semanas de filmagem, diretor de Hollywood.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "No set todos te temeram, depois te adoraram. O trailer teve 20 milhões de views em um dia.",
  "🎥 Belgesel Teklifi": "🎥 Proposta de Documentário",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Uma plataforma quer fazer um documentário sobre sua vida. A equipe vai te seguir no próximo camp e visitar sua cidade e família.",
  "Kafesten Kemere": "Do Octógono ao Cinturão",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "A câmera pegou tudo: corridas matinais, os momentos duros do corte, a cozinha da sua mãe. O público te conheceu.",
  "📺 Reklam Yüzü": "📺 Garoto-Propaganda",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} quer você como rosto da nova campanha. Um dia de filmagem, outdoors no país todo.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Seu rosto está em cada esquina. Sua mãe fotografa cada outdoor.",
  "🎙️ Talk Show Daveti": "🎙️ Convite para Talk Show",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "“{0}” te convidou. O apresentador é famoso; se você aguentar piada, a plateia é sua.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Você mostrou uma chave de braço no apresentador ao vivo. O clipe está em todo lugar.",
  "📰 Dergi Kapağı": "📰 Capa de Revista",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "A revista {0} quer você na capa. Um dia de fotos e uma grande entrevista.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "A edição esgotou nas bancas. Uma cópia está na parede da academia.",
  "📺 Dizi Konuk Rolü": "📺 Participação em Série",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "A série de sucesso “{0}” quer que você interprete a si mesmo em um episódio. Duas semanas de filmagem.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Sua cena rodou as redes. Os roteiristas querem você de volta na próxima temporada.",
