  "Ressam bir gecede ünlendi, sen de takipçi kazandın. Popülerlik +1, {0} takipçi.": "O pintor ficou famoso da noite para o dia e você ganhou seguidores. Popularidade +1, {0} seguidores.",
  "Ressam cevabını çerçeveletmiş. Motivasyon +1.": "O pintor emoldurou sua resposta. Motivação +1.",
