  "🏠 {0} meydanına bronz heykelin dikildi. Kemerli, kollar havada.": "🏠 Ergueram sua estátua de bronze na praça de {0}. De cinturão e braços erguidos.",
  "Eski salonun yeni minderleri, yeni torbaları ve senin adını taşıyan tabelasıyla açıldı. Çocuklar sıraya girdi. Popülerlik +3, motivasyon +1 (${0}).": "A antiga academia reabriu com tatames e sacos novos e uma placa com seu nome. As crianças fizeram fila. Popularidade +3, motivação +1 (${0}).",
  "Meydanda yürüyemedin bile; herkes fotoğraf istedi. Annenin yemeği her şeye değdi. Motivasyon +1, sağlık +5, popülerlik +1.": "Você nem conseguiu atravessar a praça; todos queriam foto. A comida da sua mãe valeu tudo. Motivação +1, saúde +5, popularidade +1.",
  "Salonda çocuklara bir antrenman verdin, akşam ailenle sofraya oturdun. Motivasyon +1, sağlık +5.": "Você deu um treino para as crianças na academia e jantou com a família. Motivação +1, saúde +5.",
