  "Kamp hazır. Haftalar kendiliğinden akacak; bir karar gerektiğinde duracak.": "O camp está pronto. As semanas passam sozinhas e param quando for preciso decidir.",
  "Sparda sert bir darbe aldın; kaburgaların sızlıyor. {0} kararı sana bırakıyor.": "Você levou um golpe forte no sparring; as costelas doem. {0} deixa a decisão com você.",
