  "DM kavgası": "Briga na DM",
  "Mesajlaşma kızıştı, kulise sızdı. Maçın gündemi yükseldi. Takipçi {0}.": "A troca esquentou e vazou. O hype da luta subiu. Seguidores {0}.",
  "İfşa": "Exposto",
  "Ekran görüntüsü yayıldı, herkes rakibin tehdidini konuşuyor. Takipçi {0}.": "O print se espalhou, todos falam da ameaça. Seguidores {0}.",
