  "{0} bölüm": "{0} capítulos",
  "Ya da bir efsaneyi yaşa": "Ou viva a história de uma lenda",
  "{0}: Dublin'den çifte şampiyonluğa, rehberli 9 bölüm. Ücretsiz.": "{0}: de Dublin a campeão em duas categorias, 9 capítulos guiados. Grátis.",
