  "EFSANE YOLU · BÖLÜM 1 TAMAMLANDI": "CAMINHO DA LENDA · CAPÍTULO 1 CONCLUÍDO",
  "HİKÂYE BURADA BİTMİYOR": "A HISTÓRIA NÃO TERMINA AQUI",
  "Sıradaki bölüm: {0} ({1}). Önünde {2} bölüm daha var.": "Próximo capítulo: {0} ({1}). Faltam mais {2} capítulos.",
  "{0} hikâyesine kaldığın yerden devam et:": "Continue a história de {0} de onde parou:",
  "Paket almadan da bu kariyere normal devam edebilirsin; yalnızca bölüm hedefleri ilerlemez.": "Você pode continuar esta carreira sem o pacote; só os objetivos de capítulo não avançam.",
  "SIRADAKİ EFSANE": "PRÓXIMA LENDA",
  "ŞAMPİYONSUN. SIRADA EFSANELER VAR": "VOCÊ É CAMPEÃO. AGORA, AS LENDAS",
  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Depois de conquistar o cinturão, {0} levou o MMA feminino ao mundo. Viva o caminho dela capítulo a capítulo.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} carregou este cinturão com um cartel invicto de 29-0. Viva o caminho dele capítulo a capítulo.",
  "İstersen önce menüdeki Efsane Yolları'ndan her efsanenin 1. bölümünü ücretsiz dene.": "Você pode experimentar grátis o capítulo 1 de cada lenda em Caminhos da Lenda, no menu.",
  "{0} nasıl efsane oldu?": "Como {0} virou lenda?",
  "Hikâyesini bölüm bölüm oyna.": "Jogue a história capítulo a capítulo.",
  "Hikâyesini oyna: 1. bölüm ücretsiz.": "Jogue a história: o capítulo 1 é grátis.",
  "Efsaneler Paketi dahil: bütün Efsane Yolları hikâyeleri": "Pacote de Lendas incluso: todas as histórias de Caminhos da Lenda",
  "🔒 {0} hikâyesinin devamı Efsaneler Paketi'nde. Kariyerine normal devam edebilirsin.": "🔒 O resto da história de {0} está no Pacote de Lendas. Você pode continuar sua carreira normalmente.",
  "📖 EFSANE YOLU DEVAM EDİYOR: Bölüm {0}.": "📖 O CAMINHO DA LENDA CONTINUA: capítulo {0}.",
  "Bütün oyun modları": "Todos os modos de jogo",
  "Geçiş reklamları": "Anúncios intersticiais",
