  "{0} efsanenin tamamı": "Todas as {0} lendas",
  "Altın Seri ve Şampiyon çerçevesi": "Série Ouro e moldura de Campeão",
  "Şampiyon ol · {0}": "Seja Campeão · {0}",
  "BUGÜN 3 REKLAM İZLEDİN": "VOCÊ VIU 3 ANÚNCIOS HOJE",
  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "Com o Pacote Campeão todos os prêmios chegam na hora, sem anúncios. Compra única, sem assinatura.",
  "BÜTÜN YUVALAR DOLU": "TODOS OS ESPAÇOS ESTÃO CHEIOS",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "O Pacote Campeão dá 5 espaços de carreira: não precisa apagar uma história para começar outra.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "UM PACOTE À ALTURA DE UM CAMPEÃO",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Você ganhou o cinturão. Desbloqueie todos os extras com o Pacote Campeão.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Sem anúncios e na hora com o Pacote Campeão",
  "👑 ŞAMPİYON PAKETİ": "👑 PACOTE CAMPEÃO",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Os dois lutadores que quiser, no peso que quiser, quantas vezes quiser. Coloque também suas próprias lendas contra as lendas.",
  "Hayalî Maç Stüdyosu": "Estúdio de Lutas dos Sonhos",
  "Rövanş": "Revanche",
  "Yeni eşleşme": "Novo confronto",
  "Hayalî Maçlar'a dön": "Voltar a Lutas dos Sonhos",
  "HAYALÎ MAÇ STÜDYOSU": "ESTÚDIO DE LUTAS DOS SONHOS",
  "Kimi yöneteceksin?": "Quem você vai controlar?",
  "Rakibini seç.": "Escolha seu adversário.",
  "Kırmızı köşe": "Córner vermelho",
  "Mavi köşe": "Córner azul",
  "Emekli olan dövüşçülerini emeklilik ekranından Efsanelerim'e ekleyebilirsin; burada efsanelere karşı dövüşürler.": "Você pode adicionar seus lutadores aposentados a Minhas Lendas pela tela de aposentadoria; aqui eles lutam contra as lendas.",
  "⭐ Efsanem": "⭐ Minha lenda",
  "Rakibi değiştir": "Trocar adversário",
  "Zirvedeki halleriyle · 5 raunt": "No auge · 5 rounds",
  "{0} vs {1}": "{0} vs {1}",
  "İstediğin iki dövüşçü, istediğin sıklet, sınırsız maç. Kendi efsanelerin de burada.": "Os dois lutadores que quiser, em qualquer peso, lutas ilimitadas. Suas próprias lendas também estão aqui.",
  "⭐ Efsanelerinde · Hayalî Maç Stüdyosu'nda dövüşebilir": "⭐ Em Minhas Lendas · pode lutar no Estúdio de Lutas dos Sonhos",
