  "⭐ Efsanelerime ekle (Hayalî Maç Stüdyosu)": "⭐ Adicionar a Minhas Lendas (Estúdio de Lutas dos Sonhos)",
  "⭐ EFSANELERİM": "⭐ MINHAS LENDAS",
  "{0} zirvedeki haliyle kaydedilsin; Hayalî Maç Stüdyosu'nda Conor'a, Khabir'e ve diğer efsanelere karşı dövüşsün.": "Salve {0} no auge e coloque contra Conor, Khabir e as outras lendas no Estúdio de Lutas dos Sonhos.",
  "✓ Efsanelerinde": "✓ Em Minhas Lendas",
  "Efsanelerim dolu ({0}/{1}). Şampiyon Paketi ile 10 efsane kaydedebilirsin ya da eskisinin yerine kaydedebilirsin.": "Minhas Lendas está cheio ({0}/{1}). Salve até 10 lendas com o Pacote Campeão ou substitua a anterior.",
