  "SEZON {0} · {1} GÜN KALDI": "TEMPORADA {0} · FALTAM {1} DIAS",
  "Sezon tamamlandı!": "Temporada concluída!",
  "Sonraki basamak: {0}/{1} puan": "Próximo nível: {0}/{1} pontos",
  "Puan: maç +{0}, galibiyet +{1}, bitiriş +{2}, Günün Dövüşü +{3}, Hayalî Maç +{4}, efsane bölümü +{5}": "Pontos: luta +{0}, vitória +{1}, finalização +{2}, Luta do Dia +{3}, Luta dos Sonhos +{4}, capítulo de lenda +{5}",
  "👑 ŞAMPİYON SIRASI": "👑 TRILHA CAMPEÃO",
  "Şampiyon Paketi ile her sezon 6 ödül daha: efsanevi sezon şortu, kemer, giriş efekti… Ulaştığın basamakların ödülleri hemen açılır.": "Com o Pacote Campeão, 6 prêmios a mais por temporada: calção lendário, cinturão, efeito de entrada… Os prêmios dos níveis já alcançados liberam na hora.",
  "Her ay yeni sezon, yeni tema. Sezon bitince alınmayan ödüller kaybolur; aldıkların dolabında kalır.": "Todo mês, nova temporada e novo tema. Prêmios não resgatados somem no fim; os resgatados ficam no seu vestiário.",
