  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Aquela noite nunca saiu da sua cabeça. A chave no pescoço, a arena em silêncio, os que pularam a grade.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "E se tudo tivesse sido diferente? E se a revanche tivesse mesmo acontecido?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Khabir Nurmagaliev ainda é o dono do cinturão. Desta vez você vai mantê-lo em pé e ditar a distância.",
  "Khabir Nurmagaliev'i yen": "Vença Khabir Nurmagaliev",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Volte ao peso-leve: Nurmagaliev está lá como campeão.",
  "Hafif sıklet kemerini al": "Conquiste o cinturão peso-leve",
  "Rövanş PPV payı": "Parte do PPV da revanche",
  "🔀 Tarih yeniden yazıldı: rövanşı kazanan sensin.": "🔀 A história foi reescrita: a revanche é sua.",
