  "Onun gelmesine izin ver, açığını yakala.": "Deixe vir e pegue a brecha.",
  "Tempoyu düşür, nefeslen": "Diminua o ritmo, respire",
  "Bu raundu idareli geçir, sonrasına güç sakla.": "Administre este round, guarde energia.",
  "Şimdi bitir!": "Finaliza agora!",
  "Sarsıldıysa üstüne çullan. Değilse pahalıya patlar.": "Se estiver balançado, vá pra cima. Se não, sai caro.",
  "Kesiği kapat": "Feche o corte",
  "Cutman'e öncelik ver: doktor maçı durdurmasın.": "Prioridade ao cutman: que o médico não pare a luta.",
  "Erken baskıcı: ilk rauntta yüklenir, sonra düşer.": "Pressão inicial: aperta no 1º round e depois cai.",
  "Kontracı: üstüne gelinmesini bekler, açığı cezalandırır.": "Contra-atacante: espera você ir e pune as brechas.",
  "Güreşçi: indirmeye ve kafes kenarında boğmaya çalışır.": "Wrestler: busca quedas e amassa na grade.",
  "Geç açılan: yavaş başlar, son rauntlarda güçlenir.": "Começo lento: começa devagar e cresce no fim.",
  "Ağır el: az atar ama tek vuruşla maçı bitirebilir.": "Mão pesada: solta pouco, mas um golpe pode acabar.",
  "Söz dinler": "Disciplinado",
  "Talimatları harfiyen uygular.": "Segue as instruções à risca.",
  "İnatçı": "Teimoso",
  "Bazen köşeyi duymaz, kendi bildiğini yapar.": "Às vezes ignora o córner e faz do seu jeito.",
  "Sinirli": "Esquentado",
  "Baskı ve bitiriş talimatlarında coşar, sabırda zorlanır.": "Cresce com pressão e finalização, sofre com paciência.",
  "Sabırlı oyunda ustadır, çılgın baskıda bocalar.": "Mestre do jogo paciente, sofre na pressão louca.",
  "{0}. raunt: {1} raundu açık ara aldı.": "Round {0}: {1} venceu com folga.",
  "{0}. raunt: {1} her yerde üstündü, {2} cevap bulamadı.": "Round {0}: {1} foi melhor em tudo, {2} não achou resposta.",
  "{0}. raunt: kartlar net, raundu {1} aldı.": "Round {0}: claro nas papeletas, foi de {1}.",
  "{0}. raunt: çekişmeli ama son saniyelerde {1} öne geçti.": "Round {0}: equilibrado, mas {1} passou à frente no fim.",
  "{0}. raunt: kıl payı, muhtemelen {1} aldı.": "Round {0}: por um triz, provavelmente de {1}.",
  "{0}. raunt: {1} biraz daha temizdi.": "Round {0}: {1} foi um pouco mais limpo.",
  "{0}. raunt: yakın geçti, {1} biraz daha aktifti.": "Round {0}: equilibrado, {1} foi um pouco mais ativo.",
  "{0}. raunt: kartlarda {1} önde olabilir.": "Round {0}: {1} pode estar à frente nas papeletas.",
  "{0}. raunt: {1} raundu çaldı gibi.": "Round {0}: parece que {1} roubou o round.",
  "{0}. raunt: {1} raundu domine etti.": "Round {0}: {1} dominou.",
  "{0}. raunt: zor raunt, {1} sürekli geri adım attı.": "Round {0}: round duro, {1} só andou para trás.",
  "{0}. raunt: {1} ritmi tamamen ele geçirdi.": "Round {0}: {1} tomou conta do ritmo.",
  "{0} önde. {1} çaresizleşmeye başladı.": "{0} está à frente. {1} começa a se desesperar.",
  "Kartlarda öndeyiz. Şimdi akıllı olmak lazım.": "Estamos à frente nas papeletas. Hora de ser esperto.",
  "{0} geride. Bir şeyler değişmeli.": "{0} está atrás. Algo precisa mudar.",
  "{0} ritmi buldu; böyle giderse kaybederiz.": "{0} achou o ritmo; assim a gente perde.",
  "Başa baş gidiyor. Bu raunt maçı belirleyebilir.": "Muito equilibrado. Este round pode decidir.",
  "{0} ile {1} arasında kılı kırk yaran bir maç.": "Uma luta parelha entre {0} e {1}.",
  "{0} önde ama nefes nefese. Ağzı açık, elleri düşük.": "{0} está à frente, mas ofegante. Boca aberta, mãos baixas.",
  "Puanda öndeyiz ama {0} nefesini kaybediyor.": "Estamos à frente, mas {0} está perdendo o fôlego.",
  "{0} yoruldu: elleri düşüyor, ağzından nefes alıyor.": "{0} cansou: mãos caindo, respirando pela boca.",
  "{0} bacaklarını zor taşıyor. Fırsat kapıda.": "{0} mal carrega as pernas. A chance está aí.",
  "Kesik var: {0} kaşından kanıyor, doktor köşeye bakıyor.": "Tem corte: {0} sangra no supercílio, o médico está de olho.",
  "Kesik kötü: {0} sağ gözünü zor görüyor.": "Corte feio: {0} mal enxerga com o olho direito.",
  "{0} sarsıldı, bacakları titriyor. Köşeye zor geldi.": "{0} está balançado, pernas tremendo. Mal chegou ao córner.",
  "Son yumrukla {0} sallandı. Gözleri dalgın.": "{0} sentiu o último soco. Olhar perdido.",
  "{0} sarsıldı! Köşesine sendeleyerek gitti.": "{0} está balançado! Voltou cambaleando ao córner.",
  "{0} ayakta zor duruyor, gözleri kaydı.": "{0} mal fica em pé, olhar perdido.",
  "{0} indirip kafese dayıyor; {1} altta eziliyor.": "{0} derruba e prensa na grade; {1} está sendo amassado por baixo.",
  "Raundun yarısı yerde geçti, {0} üstte kontrol etti.": "Metade do round no chão, {0} controlou por cima.",
  "{0} ön bacağına basamıyor, topallıyor.": "{0} não consegue apoiar a perna da frente, mancando.",
  "Tekmeler işledi: {0} artık rahat basamıyor.": "Os chutes funcionaram: {0} já não apoia direito.",
  "Gövdeye gelen her vuruşta {0} eğiliyor, dirsekleri iniyor.": "A cada golpe no corpo {0} se curva e baixa os cotovelos.",
  "{0} karaciğerini korumak için elleri indiriyor.": "{0} está baixando as mãos para proteger o fígado.",
  "Doktor durdurdu (TKO)": "Interrupção médica (TKO)",
  "🙉 {0} talimatı duymadı, kendi bildiğini yaptı.": "🙉 {0} não ouviu a instrução e fez do seu jeito.",
  "🗣️ Talimat işledi: {0}.": "🗣️ A instrução funcionou: {0}.",
  "🗣️ {0} bu raunda uymadı.": "🗣️ {0} não combinou com este round.",
  "🗣️ {0}: fena değil ama fark yaratmadı.": "🗣️ {0}: nada mal, mas não fez diferença.",
  "🗣️ Köşeden {0} talimat, {1} tanesi maçı çevirdi.": "🗣️ {0} instruções do córner, {1} viraram a luta.",
  "🔎 Keşif raporu yanılmış: {0}": "🔎 O relatório de olheiro errou: {0}",
