  "🏛️ TARİH YAZILDI! {0}: artık tüm zamanların 1 numarası sensin, {1} geride kaldı. +${2}, popülerlik +{3}.": "🏛️ HISTÓRIA! {0}: agora você é o número 1 de todos os tempos, à frente de {1}. +${2}, popularidade +{3}.",
  "🏛️ Rekor: {0} listesinde {1} dövüşçüsünü geçtin, sıran #{2}. +${3}, popülerlik +{4}.": "🏛️ Recorde: você passou {1} na lista «{0}». Você é o #{2}. +${3}, popularidade +{4}.",
  "UCC Tarihi": "História do UCC",
  "{0} tarihin 1 numarası: {1}. Bu rekor uzun süre konuşulacak.": "{0}, número 1 da história: {1}. Esse recorde vai dar o que falar por muito tempo.",
  "📰 {0}: {1} rekoruna bir adım kaldı!": "📰 {0}: a um passo do recorde de {1}!",
  "Nakavtçı": "Nocauteador",
  "Yumruğun konuşuyor. Sert vuruşların rakibi daha sık sarsar.": "Seus punhos falam. Seus golpes duros abalam o rival com mais frequência.",
  "Boğucu Güreşçi": "Grappler Sufocante",
  "Yere inen kalkamıyor. Yerde kilit fırsatın daha sık gelir.": "Quem cai não levanta. As chances de finalização vêm com mais frequência.",
  "Taktisyen": "Estrategista",
  "Aklınla dövüşüyorsun. Rakip seni daha geç okur, köşen zaafları daha çabuk bulur.": "Você luta com a cabeça. O rival demora a ler você e seu córner acha as fraquezas mais cedo.",
  "Salonu ayağa kaldırıyorsun. Galibiyetler daha çok popülerlik getirir.": "Você levanta a torcida. As vitórias trazem mais popularidade.",
  "{0} Dövüş kimliğin oluştu: {1}! {2}": "{0} Sua identidade de luta surgiu: {1}! {2}",
  "{0} Kimliğin değişti: artık bir {1}. {2}": "{0} Sua identidade mudou: agora, {1}. {2}",
  "{0} için herkes aynı şeyi söylüyor: {1}.": "Todos dizem o mesmo sobre {0}: {1}.",
  "🗞️ {0}: \"Sert vurduğunu biliyorum. Çenemi çalıştırdım.\"": "🗞️ {0}: \"Sei que você bate forte. Trabalhei o queixo.\"",
  "🗞️ {0} kampında tek konu: nakavtçıya karşı nasıl ayakta kalınır?": "🗞️ Um só assunto no camp de {0}: como ficar de pé contra um nocauteador.",
  "🗞️ {0} bütün kampı güreş savunmasıyla geçirdi: \"Beni yere indiremeyecek.\"": "🗞️ {0} passou o camp todo na defesa de quedas: \"Você não vai me derrubar.\"",
  "🗞️ {0}: \"Herkes yerde boğuluyor, ben boğulmayacağım.\"": "🗞️ {0}: \"Todo mundo sufoca no chão. Eu não.\"",
  "🗞️ {0}: \"Çok düşünüyor. Ona düşünecek vakit bırakmayacağım.\"": "🗞️ {0}: \"Você pensa demais. Não vou dar tempo para pensar.\"",
  "🗞️ {0} kampı senin maçlarını kare kare izliyor.": "🗞️ O camp de {0} estuda suas lutas quadro a quadro.",
  "🗞️ {0}: \"Kafes sirk değil. Şovunu bitireceğim.\"": "🗞️ {0}: \"O cage não é circo. Vou acabar com seu show.\"",
  "🗞️ {0} basına konuştu: \"Bu kadar gösteriş yeter.\"": "🗞️ {0} disse à imprensa: \"Chega de exibição.\"",
  "TARİHİN EN İYİLERİ": "OS MELHORES DA HISTÓRIA",
  "Yalnızca UCC maçları sayılır. Her efsaneyi geçince para ve popülerlik kazanırsın.": "Só lutas do UCC contam. Passe cada lenda para ganhar dinheiro e popularidade.",
  "UCC'ye çıktığında bu listede yarışmaya başlarsın.": "Você começa a competir nesta lista ao chegar ao UCC.",
