  "REKORLAR": "RECORDES",
  "ŞAMPİYON SAATİ": "HORA DO CAMPEÃO",
  "Şu an geçiş reklamı yok, ödüller reklamsız geliyor. Tadını çıkar!": "Agora não há anúncios intersticiais e as recompensas vêm sem anúncios. Aproveite!",
