  "🏅 Sezon Şampiyonu rozetlerin: {0}": "🏅 Suas medalhas de Campeão da Temporada: {0}",
  "20. basamağı bitiren kalıcı Sezon Şampiyonu rozeti kazanır.": "Chegue ao nível 20 para ganhar uma medalha permanente de Campeão da Temporada.",
