  "Tam Paket'e yükselt: Hakem + Antrenör Modu ve 6 kozmetik paket": "Melhore para Pacote Completo: Modo Árbitro + Treinador e 6 pacotes cosméticos",
  "📊 Piyasa araştırması: ücrette en fazla %{0}, galibiyet bonusunda en fazla %{1} artışa razı olurlar.": "📊 Pesquisa de mercado: aceitam no máximo +{0}% na bolsa e +{1}% no bônus por vitória.",
  "Yeni adaylar": "Novos talentos",
  "Gözcün bu dönem bir tur daha atsın: üç yeni aday gelsin.": "Seu olheiro faz mais uma rodada neste período: chegam três novos talentos.",
  "Piyasa araştırması": "Pesquisa de mercado",
  "Menajerin piyasayı tarasın: ücrette ve bonusta nereye kadar esneyeceklerini kesin öğren.": "Seu empresário analisa o mercado: descubra exatamente até onde eles cedem na bolsa e no bônus.",
  "Teklifleri yenile": "Renovar ofertas",
  "Birkaç telefon aç: organizasyonları kırmadan yeni maç teklifleri gelsin.": "Faça algumas ligações: receba novas ofertas de luta sem desagradar nenhuma organização.",
  "📞 Birkaç telefon açtın: masada yeni maç teklifleri var.": "📞 Você fez algumas ligações: há novas ofertas de luta na mesa.",
  "Büyük lig": "Liga principal",
  "Hırslı": "Ambicioso",
  "Sürekli dövüşmek ister, zor maçlardan kaçmaz. Bekletilmekten nefret eder.": "Quer lutar o tempo todo e nunca foge de luta difícil. Odeia ficar esperando.",
  "Sadık": "Leal",
  "Sana güvenir, kolay kolay gitmez. Ama kırılırsa unutmaz.": "Confia em você e não sai fácil. Mas, se magoado, nunca esquece.",
  "Rahat": "Tranquilo",
  "Yetenekli ama kamptan kaytarır. Gelişimi yavaş, sürprizi bol.": "Talentoso, mas mata o camp. Evolui devagar, cheio de surpresas.",
  "Şov adamı": "Showman",
  "Kameraları sever. Takipçi ve sponsor getirir, başını da belaya sokar.": "Ama as câmeras. Traz seguidores e patrocinadores, e problemas também.",
  "Paragöz": "Interesseiro",
  "Önce para. Daha iyi teklifi duyunca kapıyı çalan ilk kişidir.": "Dinheiro em primeiro lugar. É o primeiro a bater na porta quando aparece uma oferta melhor.",
  "Rövanş hakkı": "Cláusula de revanche",
  "Kaybedersen hemen rövanş istenebilir.": "Se perder, a revanche pode ser exigida na hora.",
  "Çıkış maddesi": "Cláusula de saída",
  "Daha üst ligden teklif gelirse bedelsiz ayrılırsın.": "Se uma liga maior fizer uma oferta, você sai de graça.",
  "Münhasırlık": "Exclusividade",
  "Organizasyon ister: ücret +%15, ama başka hiçbir teklife bakamazsın.": "A organização exige: bolsa +15%, mas você não pode olhar nenhuma outra oferta.",
  "Sakatlık güvencesi": "Proteção contra lesão",
  "Sakatken kadrodan çıkarılamaz, maaşın yarısı ödenir.": "Não pode ser dispensado enquanto lesionado, e metade da bolsa é paga.",
