  "Sıfırdan": "Do zero",
  "Elinde tek bir sokak dövüşçüsü ve kirası ödenmemiş bir bodrum ofis var. Her şey sana bağlı.": "Você só tem um lutador de rua e um escritório no porão com o aluguel atrasado. Tudo depende de você.",
  "Tek yıldız": "Uma estrela",
  "Kadronda bir UCC şampiyonu var, ama sözleşmesi bitmek üzere ve rakip ajanslar kapıda. Onu kaybetme.": "Você tem um campeão do UCC no elenco, mas o contrato está acabando e agências rivais estão na porta. Não o perca.",
  "Batık ajansı kurtar": "Salve a agência falida",
  "Önceki menajerden borç ve sana küskün üç dövüşçü devraldın. Bir yılda borcu kapat.": "Você herdou dívidas do empresário anterior e três lutadores ressentidos com você. Quite a dívida em um ano.",
  "Yurt dışı yetenekleri": "Talentos do exterior",
  "Brezilya ve Dağıstan'dan iki genç yetenek getirdin. Vize, dil ve gurbet sorunlarıyla yıldız yap.": "Você trouxe dois jovens talentos do Brasil e do Daguestão. Faça deles estrelas entre vistos, idioma e saudade de casa.",
  "Menajer": "Empresário",
  "{0} Yönetim": "{0} Gestão",
  "İlk yılında bir dövüşçünü bölgesel lige taşı.": "Leve um dos seus lutadores à liga regional no primeiro ano.",
  "Abi, otoparktaki dövüşleri bırakıp gerçek bir kafese çıkmak istiyorum. Sana güveniyorum. Beni bir yere götür.": "Irmão, quero largar as lutas de estacionamento e subir num cage de verdade. Confio em você. Me leva pra algum lugar.",
  "{0} ile yeni sözleşme imzala, onu rakip ajanslara kaptırma.": "Assine um novo contrato com {0} e não o perca para agências rivais.",
  "Sözleşmem bir maç sonra bitiyor. Telefonum susmuyor, herkes beni istiyor. Sen beni neden tutmalıyım, onu düşünüyorum.": "Meu contrato acaba depois de mais uma luta. Meu telefone não para, todo mundo me quer. Estou pensando por que deveria ficar com você.",
  "Bir yıl içinde borcu kapat (para sıfırın üstüne çıksın).": "Quite a dívida em um ano (deixe o caixa acima de zero).",
  "Ajansınızın {0} borcu bulunmaktadır. Kira ödemeleri devam ettikçe borç büyüyecektir.": "Sua agência deve {0}. A dívida vai crescer enquanto o aluguel continuar vencendo.",
  "Eski menajer paramızı yedi. Sen farklı mısın, göreceğiz.": "O empresário antigo comeu nosso dinheiro. Vamos ver se você é diferente.",
  "İki yeteneğinden birini büyük lige taşı.": "Leve um dos seus dois talentos à liga principal.",
  "Burası çok soğuk, abi. Annem her gün arıyor. Ama söz verdim, kemerle döneceğim.": "Aqui é muito frio, irmão. Minha mãe liga todo dia. Mas eu prometi, volto com o cinturão.",
  "Ofis dolu. Yeni dövüşçü için ofisi büyüt ya da birini bırak.": "O escritório está cheio. Amplie o escritório para um novo lutador ou dispense alguém.",
  "İmza parası için yeterli paran yok.": "Você não tem dinheiro suficiente para as luvas de assinatura.",
  "{0} teklifini reddetti ve {1} ile anlaştı.": "{0} recusou sua oferta e assinou com {1}.",
  "Hafta {0}: {1} kadroya katıldı (%{2}).": "Semana {0}: {1} entrou no elenco ({2}%).",
  "✍️ {0} ajansına katıldı!": "✍️ {0} entrou para a agência!",
  "Hafta {0}: {1} ile yollar ayrıldı.": "Semana {0}: você se separou de {1}.",
  "Hafta {0}: Çıkış maddesi işledi, {1} bedelsiz ayrıldı.": "Semana {0}: a cláusula de saída foi acionada, {1} saiu de graça.",
  "Hafta {0}: {1} sözleşmesini {2} bedelle feshetti.": "Semana {0}: {1} rescindiu o contrato por {2}.",
  "{0}! Rüya gibi. Bunu sana borçluyum.": "{0}! Parece um sonho. Devo isso a você.",
  "Annemi aradım, ağladı. {0} sözleşmesi, inanamıyorum.": "Liguei pra minha mãe, ela chorou. Um contrato com o {0}, não acredito.",
  "Daha yeni başlıyoruz. {0}'de herkes adımı öğrenecek.": "Estamos só começando. No {0} todo mundo vai aprender meu nome.",
  "Hafta {0}: {1} için {2} ile {3} maçlık sözleşme ({4}/maç).": "Semana {0}: contrato de {3} lutas para {1} com o {2} ({4}/luta).",
  "📝 {0} artık {1} dövüşçüsü.": "📝 {0} agora é lutador do {1}.",
  "🗓️ {0} – {1} maçı {2}. haftada.": "🗓️ {0} vs {1} na semana {2}.",
  "{0}: “Teklifimiz ortada. Dinliyoruz.”": "{0}: “Nossa oferta está na mesa. Estamos ouvindo.”",
  "{0}: “Son teklifimiz {1}. İmzala ya da yolumuza bakalım.”": "{0}: “Nossa oferta final é {1}. Assine ou cada um segue seu caminho.”",
  "{0}: “Tamam, {1} olsun.”": "{0}: “Tudo bem, fica {1}.”",
  "{0}: “Peki. Maç başı {1}.”": "{0}: “Certo. {1} por luta.”",
  "{0}: “Zorluyorsun ama olur: {1}.”": "{0}: “Você está forçando, mas tudo bem: {1}.”",
  "{0}: “Bütçeyi zorluyorsun. {1} yapabiliriz.”": "{0}: “Você está esticando o orçamento. Podemos fazer {1}.”",
  "{0}: “Kazanırsa hak eder. Bonus {1}.”": "{0}: “Se vencer, merece. Bônus de {1}.”",
  "{0}: “Münhasırlık mı? Seve seve. Ücrete %15 ekliyoruz.”": "{0}: “Exclusividade? Com prazer. Adicionamos 15% à bolsa.”",
  "{0}: “{1}, kabul. Sözleşmeye yazıyoruz.”": "{0}: “{1}, aceito. Vamos colocar no contrato.”",
  "{0}: “Çıkış maddesi mi? Dövüşçüne yatırım yapıyoruz, kaçmasına izin vermeyiz.”": "{0}: “Cláusula de saída? Estamos investindo no seu lutador, não vamos deixá-lo escapar.”",
  "{0}: “{1} olmaz. Başka bir şey?”": "{0}: “{1}, não. Mais alguma coisa?”",
