  "MENAJER MODU": "MODO EMPRESÁRIO",
  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "Desta vez não é você quem entra no cage. A carreira, o dinheiro e a saúde dos seus lutadores estão no seu telefone.",
  "Telefonun hiç susmaz: dövüşçüler, patronlar, gazeteciler ve rakip menajerler. Her cevabın bir sonucu var.": "Seu telefone nunca para: lutadores, chefes, jornalistas e empresários rivais. Cada resposta tem consequências.",
  "Organizasyonların gizli bütçesine karşı pazarlık yap; rövanş, çıkış ve sakatlık maddeleri yıllar sonra işine yarar.": "Negocie contra o orçamento oculto das organizações; cláusulas de revanche, saída e lesão rendem frutos anos depois.",
  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Saia em busca de talentos, assine jovens negociando a comissão e se antecipe às agências rivais.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "E se dois lutadores seus disputarem o mesmo cinturão? A organização vai querer colocá-los frente a frente.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "O médico alerta, o dinheiro chama. A saúde do lutador ou o dia do pagamento?",
