  "YOL EVRENİ": "UNIVERSO YOL",
  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Todos os seus modos compartilham o mesmo mundo. Seus lutadores de carreira aparecem como adversários no Modo Empresário, e os lutadores do seu Modo Empresário enfrentam sua carreira nas ligas principais e no UCC.",
  "ÇAPRAZ MAÇ": "CRUZAMENTOS",
  "ÇAPRAZ MAÇLAR": "LUTAS CRUZADAS",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Ainda não há lutas cruzadas. Quando você chegar às ligas principais e chegarem ofertas no Modo Empresário, seus lutadores vão se enfrentar.",
  "Bağlantı için iki tarafta da dövüşçü gerekir: aktif bir kariyer ve Menajer Modu'nda aynı sıklette bir dövüşçü.": "Você precisa de lutadores dos dois lados: uma carreira ativa e um lutador da mesma categoria no Modo Empresário.",
